        if x - r < -1e-9 or x + r > 1 + 1e-9:
            return False
        if y - r < -1e-9 or y + r > 1 + 1e-9:
            return False
        for other in circles:
            if overlaps(c, other):
                return False
        return True

    def get_max_radius(x, y):
        max_r = min(x, y, 1 - x, 1 - y)
        for other in circles:
            ox, oy, or_ = other
            dist = math.sqrt((x - ox) ** 2 + (y - oy) ** 2)
            if dist > or_:
                max_r = min(max_r, dist - or_)
        return max(0, max_r)

    # First, add circles around the edges
    radius = 0.05
    for i in range(2):
        for j in range(4):
            x = 0.05 + j * 0.25 + (i * 0.125)
            y = 0.05 + i * 0.9
            if x <= 1 and y <= 1 and len(circles) < 21:
